:root{--fg:#1f2328;--muted:#6b7280;--line:#e5e7eb;--accent:#2563eb;--soft:#f7f8fa;}
*{box-sizing:border-box}
body{margin:0;background:#fff;color:var(--fg);font-family:-apple-system,"PingFang SC","Microsoft YaHei",Segoe UI,sans-serif;font-size:15px;line-height:1.75;}
.wrap{max-width:1080px;margin:0 auto;padding:48px 32px 96px;}
h1{font-size:28px;line-height:1.4;border-bottom:3px solid var(--accent);padding-bottom:14px;margin:0 0 24px;}
h2{font-size:21px;margin:44px 0 16px;padding-left:12px;border-left:5px solid var(--accent);}
h3{font-size:17px;margin:30px 0 12px;color:#111827;}
p{margin:10px 0;} ul,ol{padding-left:24px;} li{margin:5px 0;}
blockquote{margin:16px 0;padding:12px 18px;background:var(--soft);border-left:4px solid var(--muted);color:#374151;border-radius:0 6px 6px 0;}
blockquote p{margin:6px 0;}
table{border-collapse:collapse;width:100%;margin:16px 0;font-size:13.5px;display:block;overflow-x:auto;}
th,td{border:1px solid var(--line);padding:9px 12px;text-align:left;vertical-align:top;}
th{background:#f1f5f9;font-weight:600;}
tr:nth-child(even) td{background:#fcfcfd;}
code{background:var(--soft);padding:2px 6px;border-radius:4px;font-size:13px;}
pre{background:var(--soft);padding:14px 16px;border-radius:8px;overflow-x:auto;border:1px solid var(--line);}
pre code{background:none;padding:0;font-size:12.5px;line-height:1.65;}
strong{color:#111827;} hr{border:0;border-top:1px solid var(--line);margin:36px 0;}
input[type=checkbox]{margin-right:6px;}
li.task-list-item{list-style:none;margin-left:-20px;}
